"""Original offline design assets. Writes only beside this file. Python stdlib."""
from pathlib import Path
import math, random, json, shutil, html
R=Path(__file__).resolve().parent
def put(n,s):
 p=R/n;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(s,encoding='utf-8')
F=R/'assets/fonts';F.mkdir(parents=True,exist_ok=True)
for p in (R.parent/'overlay/assets/fonts').iterdir(): shutil.copyfile(p,F/p.name)
