 return '<aside class="legend"><h3>'+t('Vrstvy a filtry','Layers & filters')+'</h3><label><input id="gridToggle" type="checkbox" checked>'+t('Taktická mřížka','Tactical grid')+'</label><h4>'+t('TYP BODU','POINT TYPE')+'</h4>'+''.join(f'<label>{ic(id)}<input type="checkbox" checked data-filter-kind="{id}">{t(cs,en)}</label>' for id,cs,en,p in types)+'<h4>'+t('TYP MÍSTA','LOOT AREA')+'</h4><div class="area-filters">'+''.join(f'<label title="{n}"><input type="checkbox" checked data-filter-area="{n}">{badge(n)}</label>' for n,g,d,l,p in areas)+'</div></aside>'
