 return '<aside class="detail"><div class="eyebrow">'+t('VYBRANÝ BOD','SELECTED POINT')+'</div><h2>01 / '+t('Rozvodna','Substation')+'</h2><div class="type-line">'+ic('crate')+t('Kontejner','Container')+'</div><h4>'+t('TYP MÍSTA','LOOT AREA')+'</h4>'+badge('Electrical')+'<h4>'+t('POZNÁMKA','NOTE')+'</h4><p>'+t('Dvě bedny za severní zdí. Přístup z cesty.','Two crates behind the north wall. Access from the road.')+'</p><div class="row">'+b('Upravit','Edit','id="editPoint"')+b('Smazat','Delete','id="deletePoint"','danger')+'</div><hr><div class="eyebrow">'+t('PRO AKTIVNÍ PLÁN','FOR ACTIVE PLAN')+'</div><h3>'+t('Tady hledej','Look here')+'</h3><div class="need"><b>Power Cable</b><span>2×</span></div><div class="need"><b>Electrical Components</b><span>2×</span></div><p class="muted">'+t('Shoda podle typu místa. Výskyt není zaručen.','Matched by loot area. Spawns are not guaranteed.')+'</p><div class="callout">'+t('Body zadáváš ručně. Značka hráče není živá poloha.','Points are entered manually. Player marker is not a live location.')+'</div></aside>'
