title=t('Mapy','Maps')
nav='<nav class="sidebar"><div class="brand">ARC <em>OPS</em></div><small>COMPANION</small><div class="nav-group">'+t('RAIDY','RAIDS')+'</div><div>'+t('Příprava na raid','Raid prep')+'</div><div class="nav-active">'+title+'</div><div>'+t('Deník','Journal')+'</div><div class="nav-group">'+t('VÝBAVA','GEAR')+'</div><div>'+t('Zásoba','Inventory')+'</div><div>'+t('Úkoly','Quests')+'</div><div class="nav-foot">'+t('Pouze lokálně','Local only')+'<br><span>0.14 / DESIGN</span></div></nav>'
