plan='<div class="plan-strip"><span class="status-dot"></span><b>'+t('Plán aktivní','Plan active')+'</b><span>Gear Bench 2</span><span class="muted">'+t('3 zvýrazněné body','3 highlighted points')+'</span><label><input id="planToggle" type="checkbox" checked>'+t('Zvýraznit shody','Highlight matches')+'</label></div>'
main='<div class="app">'+nav+'<main><header><div><div class="eyebrow">'+t('TERÉNNÍ ARCHIV','FIELD ARCHIVE')+'</div><h1>'+title+'</h1></div><div class="header-meta">'+t('Vlastní snímky · vlastní body','Your screenshots · your points')+'<br><span class="muted">'+t('Neoficiální offline pomocník','Unofficial offline companion')+'</span></div></header>'+toolbar+plan+'<section class="map-layout">'+legend()+'<div class="map-stage">'+canvas()+form()+'</div>'+detail()+'</section><footer><span>'+t('Vlastní snímek • uložený jen v tomto zařízení','Your screenshot • stored on this device only')+'</span>'+b('+ Přidat bod','+ Add point','id="addPoint"')+'</footer></main></div>'
empty='<div class="app">'+nav+'<main><header><div><div class="eyebrow">'+t('TERÉNNÍ ARCHIV','FIELD ARCHIVE')+'</div><h1>'+title+'</h1></div></header>'+toolbar+'<section class="empty"><div class="empty-glyph">'+ic('note')+'</div><div class="eyebrow">'+t('VLASTNÍ MAPOVÝ PODKLAD','YOUR MAP BACKGROUND')+'</div><h1>'+t('Tvoje mapa začíná snímkem','Your map starts with a screenshot')+'</h1><p>'+t('Vlož vlastní snímek mapy ze hry. Body a plán zůstanou jen u tebe.','Add your own in-game map screenshot. Points and plan stay with you.')+'</p><ol><li>'+t('Ve hře otevři mapu a zvol celý přehled.','Open the map in game and choose the full view.')+'</li><li>'+t('Pořiď snímek systémovým nástrojem nebo nastavenou zkratkou.','Capture it with your system tool or configured shortcut.')+'</li><li>'+t('Vlož sem obrázek bez okrajů, pokaždé se stejným výřezem.','Insert the image without borders, using the same crop each time.')+'</li></ol><div class="dropzone">'+t('Přetáhni sem snímek','Drop a screenshot here')+'<div class="row">'+b('Vložit ze schránky','Paste from clipboard','data-import','primary')+b('Vybrat soubor','Choose file','data-import')+'</div><small>PNG / JPEG / WEBP</small></div><p class="muted">'+t('Žádné herní mapy nejsou přibalené. Seznam k hledání funguje i bez snímku.','No game maps are bundled. Your search list works without a screenshot.')+'</p></section><footer>'+t('Snímky se do zálohy přidávají volitelně.','Screenshots are included in backups only if you choose.')+'</footer></main></div>'
