css='''@font-face{font-family:Chakra;src:url(assets/fonts/ChakraPetch-SemiBold.ttf)}@font-face{font-family:Inter;src:url(assets/fonts/Inter.ttf)}@font-face{font-family:Jet;src:url(assets/fonts/JetBrainsMono.ttf)}
*{box-sizing:border-box}body{margin:0;background:#101315;color:var(--map-ink);font:13px/1.5 Inter,sans-serif}h1,h2,h3{font-family:Chakra,sans-serif;margin:0}h1{font-size:28px;line-height:1.25}h2{font-size:21px}h3{font-size:16px}h4,.eyebrow{font:11px/1.5 Jet,monospace;letter-spacing:.09em;color:var(--map-muted);margin:0 0 8px}h4{margin:16px 0 8px}p{margin:12px 0}button,input,select,textarea{font:inherit}button,select,input[type=search],textarea{border:1px solid var(--map-line);border-radius:4px;background:var(--map-paper);color:var(--map-ink)}button{min-height:36px;padding:6px 12px;cursor:pointer;white-space:nowrap}button:hover{background:#323A3F}button:focus-visible,input:focus-visible,select:focus-visible,textarea:focus-visible{outline:2px solid #F4AD82;outline-offset:3px}button.primary{background:#F4AD82;color:#241810;border-color:#F4AD82;font-weight:600}button.danger{color:#F09B9E}input[type=checkbox]{accent-color:#F4AD82;width:16px;height:16px;flex:none}label{display:flex;align-items:center;gap:7px;cursor:pointer}select{height:36px;padding:0 8px}small{font-size:11px}.muted{color:var(--map-muted)}.icon{width:20px;height:20px;fill:none;stroke:currentColor;stroke-width:1.7;stroke-linecap:round;stroke-linejoin:round;vertical-align:middle;flex:none}.app{width:1280px;height:800px;display:grid;grid-template-columns:150px 1fr;background:var(--map-paper)}.sidebar{background:#101315;padding:24px 14px;position:relative;color:#C8C7C2}.brand{font:24px Chakra}.brand em{color:#F4AD82;font-style:normal}.sidebar>small{font:10px Jet;letter-spacing:.2em}.nav-group{font:10px Jet;color:#A2A8AA;margin-top:38px;margin-bottom:12px}.sidebar>div:not(.brand):not(.nav-group):not(.nav-foot){padding:10px 6px}.nav-active{background:#3A302A;border-left:3px solid #F4AD82;color:#F2EEE7}.nav-foot{position:absolute;bottom:22px;font-size:11px}.nav-foot span{font:10px Jet;color:#A2A8AA}main{padding:22px 24px 0;min-width:0}header{display:flex;justify-content:space-between;align-items:center;height:68px}.header-meta{text-align:right;color:#C8C7C2;font-size:12px}.toolbar{display:flex;gap:12px;align-items:center;margin:20px 0 16px;font-size:12px}.map-select{flex-direction:column;align-items:flex-start;gap:3px;position:relative}.map-select>select{width:202px}.toggle{white-space:nowrap}.toolbar>button:last-child{margin-left:auto;font-size:11px;padding:5px 8px}.plan-strip{display:flex;gap:12px;align-items:center;background:#292A25;border:1px solid #75634F;border-left:3px solid #F4AD82;padding:10px 12px;margin-bottom:16px;height:44px;font-size:12px}.plan-strip label{margin-left:auto}.status-dot{width:7px;height:7px;background:#F4AD82;border-radius:50%}.map-layout{display:grid;grid-template-columns:180px minmax(0,1fr) 240px;gap:12px;height:532px}.legend,.detail{background:#1D2225;border:1px solid #363E43;border-radius:6px;padding:14px;overflow:auto}.legend{font-size:11px}.legend h3{font-size:14px}.legend label{margin-top:7px;gap:5px}.legend .icon{width:16px;height:16px}.area-filters{display:grid;grid-template-columns:1fr}.area-filters label{margin:5px 0}.badge{display:inline-flex;align-items:center;gap:6px;font-size:11px;font-weight:600;white-space:nowrap}.detail h2{margin:8px 0 16px}.detail p{line-height:1.65}.type-line{display:flex;align-items:center;gap:8px}.detail hr{border:0;border-top:1px solid #465158;margin:24px 0}.row{display:flex;gap:8px;justify-content:center}.detail .row{justify-content:flex-start}.need{display:flex;justify-content:space-between;font-size:12px;border-bottom:1px solid #363E43;padding:10px 0}.need span{font-family:Jet}.callout{border-left:2px solid #849095;color:#C8C7C2;font-size:11px;padding:8px 10px;margin-top:22px;background:#171D20}.map-stage{position:relative;overflow:hidden;border:1px solid #65716F;border-radius:6px}.canvas{height:100%;position:relative;overflow:hidden;background:#171D20;cursor:crosshair}.terrain-wrap{position:absolute;inset:0;transform-origin:center}.terrain{width:100%;height:100%;object-fit:cover;pointer-events:none}.harmonised{filter:var(--map-filter)}.grid{position:absolute;inset:0;background-image:linear-gradient(var(--map-grid) 1px,transparent 1px),linear-gradient(90deg,var(--map-grid) 1px,transparent 1px);background-size:64px 64px;pointer-events:none}.map-pin{position:absolute;transform:translate(-50%,-50%);background:#171D20;border:1px solid currentColor;border-radius:4px;width:36px;height:36px;min-height:36px;padding:6px;box-shadow:0 0 0 2px #F2EEE7;z-index:3}.map-pin .icon{width:22px;height:22px}.map-pin small{position:absolute;top:39px;left:50%;transform:translateX(-50%);background:#171D20;color:#F2EEE7;font:10px Jet;padding:2px 5px;border:1px solid #849095;border-radius:2px;white-space:nowrap}.map-pin.highlight{box-shadow:0 0 0 2px #171D20,0 0 0 4px currentColor,0 0 20px 3px #F4AD8250}.map-pin.highlight:before{content:'';position:absolute;inset:-10px;border:1px dashed #F2EEE7;border-radius:7px;pointer-events:none}.map-pin.selected{outline:3px solid #F2EEE7;outline-offset:5px;z-index:4}.map-pin.dimmed{filter:saturate(.2)}.map-pin.dimmed small{color:#C8C7C2}.map-pin.dragging{cursor:grabbing;outline:2px dashed #F4AD82;outline-offset:8px}.map-corner,.pan-hint,.axis,.zoom{position:absolute;z-index:5;background:#171D20;color:#C8C7C2;border:1px solid #65716F;padding:5px 8px;font:10px Jet}.map-corner{bottom:12px;left:12px}.axis{top:12px;left:12px}.pan-hint{bottom:44px;left:12px}.zoom{top:12px;right:12px;padding:0;display:flex}.zoom button{border:0;border-radius:0;font:12px Jet;padding:4px 8px}.add-form{position:absolute;z-index:8;left:24px;top:120px;width:260px;padding:20px;background:#1D2225;border:1px solid #F4AD82;box-shadow:0 16px 40px #0009;border-radius:6px}.add-form label{display:block;margin:12px 0}.add-form select,.add-form textarea{display:block;width:100%;margin-top:4px}.add-form textarea{height:60px;padding:8px}.add-form .row{justify-content:flex-end}footer{height:54px;display:flex;align-items:center;justify-content:space-between;color:#A2A8AA;font-size:11px}footer button{font-size:12px}.empty{text-align:center;padding:35px 50px}.empty p{max-width:650px;margin:16px auto;color:#C8C7C2}.empty-glyph{margin:0 auto 20px;border:1px solid #849095;width:56px;height:56px;display:grid;place-items:center;transform:rotate(-4deg)}.empty-glyph svg{width:32px;height:32px;color:#F4AD82}.empty ol{text-align:left;width:560px;margin:24px auto;line-height:2.2;color:#C8C7C2}.dropzone{padding:24px;border:1px dashed #849095;border-radius:8px;max-width:620px;margin:24px auto 0;background:#1D2225;font:18px Chakra}.dropzone .row{margin:18px 0 12px}.dropzone small{color:#A2A8AA;font:11px Jet}.overlay{width:1100px;height:760px;background:#141719F5;border:1px solid #65716F;clip-path:polygon(16px 0,100% 0,100% calc(100% - 16px),calc(100% - 16px) 100%,0 100%,0 16px);position:relative}.overlay:before{content:'';position:absolute;left:0;top:0;width:90px;height:3px;background:#F4AD82}.overlay header{height:91px;padding:0 26px}.overlay header h1{font-size:25px}.tabs{height:56px;display:flex;gap:40px;align-items:center;padding:0 26px;border-top:1px solid #363E43;border-bottom:1px solid #65716F;font:16px Chakra;color:#A2A8AA}.tabs>b{color:#F4AD82;height:56px;display:flex;align-items:center;gap:18px;border-bottom:3px solid #F4AD82;min-width:90px}.tabs small{font:11px Jet}.raid-content{height:546px;padding:22px 26px;display:grid;grid-template-columns:1fr 420px;gap:26px}.section-head{display:flex;align-items:center;justify-content:space-between;margin-bottom:14px}.section-head span{font-size:12px}.search-row{border:1px solid #465158;border-radius:4px;margin-bottom:8px;padding:10px 12px;min-height:62px;background:#1D2225;gap:12px}.search-row>span{flex:1}.search-row .badge{display:flex;margin-top:3px}.search-row strong{font:20px Chakra}.search-row:has(input:checked){opacity:.65}.search-row:has(input:checked) b{text-decoration:line-through}.lookup{margin-top:18px;border-top:1px solid #65716F;padding-top:14px}.lookup h3{margin-bottom:10px}.lookup label{font-size:11px;display:block}.lookup input{height:36px;width:100%;padding:8px;margin:4px 0 10px}.advice{background:#22352C;border-left:3px solid #91CFAB;padding:10px 12px;display:grid;grid-template-columns:72px 1fr;gap:0 8px}.advice>b{font:12px Jet;color:#91CFAB}.advice strong{font-size:12px}.advice p{grid-column:2;margin:3px 0;font-size:12px}.lookup>small{display:block;margin-top:8px}.raid-map .canvas{height:310px;border:1px solid #65716F;border-radius:4px}.mini .map-pin{width:28px;height:28px;min-height:28px;padding:3px}.mini .map-pin .icon{width:20px;height:20px}.mini .map-pin small{top:30px;font-size:9px}.mini .map-pin.dimmed{display:none}.mini .map-corner{font-size:8px;padding:4px;bottom:8px;left:8px}.mini-legend{display:flex;gap:18px;margin-top:16px}.raid-map p{font-size:12px;line-height:1.8}.overlay footer{height:67px;padding:0 26px;border-top:1px solid #65716F}.toast{position:fixed;bottom:14px;left:50%;transform:translateX(-50%);background:#F4AD82;color:#241810;padding:12px 24px;border-radius:6px;z-index:100}.swatches{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}.swatch{padding:12px;border:1px solid #849095;border-radius:6px}.swatch .badge{font-size:14px}.review{max-width:1328px;margin:auto;padding:36px 24px}.review>section{margin:48px 0}.review img{max-width:100%;height:auto;display:block;border:1px solid #465158}.review a{color:#F4AD82}.review h2{margin-bottom:16px}.review .lead{max-width:780px;font-size:16px;color:#C8C7C2}.comparison{display:grid;grid-template-columns:1fr 1fr;gap:20px}.comparison img{height:290px;width:100%;object-fit:cover}.icon-matrix{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}.icon-cell{padding:16px;border:1px solid #465158;display:flex;gap:16px;align-items:center}.icon-cell img{width:auto;border:0}.state-samples{display:flex;gap:22px;padding:50px 20px;background:#727B68}.state-samples>div{position:relative;width:130px;height:90px}.state-samples .map-pin{left:50%;top:20%}.state-samples span{position:absolute;bottom:0;background:#171D20;color:#F2EEE7;padding:4px 8px}.tone{padding:18px;background:#777}.tone.light{background:#F2EEE7;color:#242A2E}.tone .swatches{grid-template-columns:repeat(4,1fr)}[hidden]{display:none!important}@media(prefers-reduced-motion:reduce){*{animation:none!important;transition:none!important}}
'''
