put('maps.css',css)
js='''const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)],q=new URLSearchParams(location.search);function toast(s){$('.toast')?.remove();let e=document.createElement('div');e.className='toast';e.role='status';e.textContent=s;document.body.append(e)}
const form=$('#pointForm');function openForm(){if(form){form.hidden=false;form.querySelector('select').focus()}}$('#addPoint')?.addEventListener('click',openForm);$('#editPoint')?.addEventListener('click',openForm);$('#cancelPoint')?.addEventListener('click',()=>form.hidden=true);form?.addEventListener('submit',e=>{e.preventDefault();form.hidden=true;toast('Ukázka: bod uložen pouze do náhledu.');let pin=$('.map-pin').cloneNode(true);pin.className='map-pin';pin.style.left='45%';pin.style.top='67%';pin.querySelector('small').textContent='09 · E';$('.terrain-wrap').append(pin)});$$('.mini .map-pin').forEach(p=>{p.tabIndex=-1;p.setAttribute('aria-disabled','true')});if(q.has('add'))openForm();document.addEventListener('keydown',e=>{if(e.key==='Escape'&&form)form.hidden=true});
let z=1;function zoom(){if($('.terrain-wrap'))$('.terrain-wrap').style.transform=`translate(${dx}px,${dy}px) scale(${z})`;if($('#resetZoom'))$('#resetZoom').textContent=Math.round(z*100)+' %'}let dx=0,dy=0;$('#zoomIn')?.addEventListener('click',()=>{z=Math.min(3,z+.25);zoom()});$('#zoomOut')?.addEventListener('click',()=>{z=Math.max(1,z-.25);zoom()});$('#resetZoom')?.addEventListener('click',()=>{z=1;dx=dy=0;zoom()});$('#gridToggle')?.addEventListener('change',e=>$$('.grid').forEach(x=>x.hidden=!e.target.checked));$('#harmonise')?.addEventListener('change',e=>$$('.terrain').forEach(x=>x.classList.toggle('harmonised',e.target.checked)));$('#planToggle')?.addEventListener('change',e=>$$('.map-pin').forEach(x=>{if(['01','02','03'].includes(x.dataset.number))x.classList.toggle('highlight',e.target.checked)}));
function filter(){let kinds=$$('[data-filter-kind]:checked').map(x=>x.dataset.filterKind),areas=$$('[data-filter-area]:checked').map(x=>x.dataset.filterArea);$$('.map-pin').forEach(x=>x.hidden=!kinds.includes(x.dataset.kind)||!areas.includes(x.dataset.area))}$$('[data-filter-kind],[data-filter-area]').forEach(x=>x.onchange=filter);
$$('.map-pin').forEach(pin=>pin.addEventListener('click',e=>{e.stopPropagation();$$('.map-pin').forEach(p=>p.classList.remove('selected'));pin.classList.add('selected');if($('.detail h2')){$('.detail h2').textContent=pin.dataset.number+' / '+pin.getAttribute('aria-label');$('.detail .type-line').textContent=pin.getAttribute('aria-label');$('.detail> .badge').outerHTML=`<span class="badge">${pin.dataset.area}</span>`;$('.detail>p').textContent='Ukázkový vlastní bod.'}}));
const c=$('#mapCanvas');let down=null,moved=false;c?.addEventListener('pointerdown',e=>{if(e.target.closest('button'))return;down=[e.clientX,e.clientY,dx,dy];moved=false;c.setPointerCapture(e.pointerId)});c?.addEventListener('pointermove',e=>{if(!down)return;if(Math.abs(e.clientX-down[0])+Math.abs(e.clientY-down[1])>5)moved=true;if(moved){dx=down[2]+e.clientX-down[0];dy=down[3]+e.clientY-down[1];zoom()}});c?.addEventListener('pointerup',()=>{if(down&&!moved)openForm();down=null});$('#deletePoint')?.addEventListener('click',()=>{toast('Ukázka: bod smazán. V aplikaci nabídnout Zpět.');$('.map-pin.selected')?.remove()});
$$('#changeShot,[data-import],[data-demo],#webMap').forEach(e=>e.onclick=()=>toast('Návrhová ukázka — bez načítání souboru a bez otevření webu.'));$('#lookupInput')?.addEventListener('input',e=>{let v=e.target.value.toLowerCase(),a=$('#advice');a.style.borderColor='#91CFAB';if(v.includes('cable'))a.innerHTML='<b>NECHAT</b><strong>Power Cable</strong><p>2 ks chybí pro Gear Bench 2.</p>';else if(v.includes('sell')){a.innerHTML='<b>PRODAT</b><strong>Ukázkový předmět</strong><p>Není potřeba pro zvolené cíle. Ukázka rozhodnutí.</p>';a.style.borderColor='#E6C66D'}else if(v.includes('recycle')){a.innerHTML='<b>RECYKLOVAT</b><strong>Ukázkový předmět</strong><p>Materiál pro zvolený cíl. Ukázka rozhodnutí.</p>';a.style.borderColor='#91BDE6'}else a.innerHTML='<b>—</b><strong>Bez výsledku</strong><p>Zkus jiný název předmětu.</p>'});
'''
put('mockup.js',js)
def page(title,body,script=True):return f'<!doctype html><html lang="cs"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title} · ARC OPS design</title><link rel="stylesheet" href="tokens.css"><link rel="stylesheet" href="maps.css"><body><svg xmlns="http://www.w3.org/2000/svg" aria-hidden="true" style="position:absolute;width:0;height:0;overflow:hidden"><defs>{symbols}</defs></svg>{body}'+('<script src="mockup.js"></script>' if script else '')+'</body></html>'
put('viewer.html',page('Mapy',main));put('empty.html',page('Bez snímku',empty));put('raid.html',page('Raid',overlay));put('raid-empty.html',page('Bez plánu',overlay_empty))
swatches=''.join(f'<div class="swatch">{badge(n)}<p><code>{d} / {l}</code></p></div>' for n,g,d,l,p in areas)
matrix=''.join(f'<div class="icon-cell">'+''.join(f'<img style="color:#F2EEE7;background:#F2EEE7" src="assets/icons/{id}.svg" width="{s}" height="{s}" alt="{cs}, {s} px">' for s in [16,20,24])+f'<span>{cs}</span></div>' for id,cs,en,p in types)
# SVG files use currentColor (black standalone); matrix uses black glyphs on cream chips.
states=''.join(f'<div><button class="map-pin {cl}" style="color:#E6D16F">{ic("crate")}<small>01 · E</small></button><span>{label}</span></div>' for cl,label in [('','Výchozí'),('hovered','Hover / fokus'),('selected','Vybraný'),('highlight','Pro plán'),('dimmed','Ostatní'),('dragging','Tažení')])
review='<div class="review"><div class="eyebrow">ARC OPS / DESIGN SYSTEM / 12.11.2026</div><h1>Mapy, které patří hráči.</h1><p class="lead">Taktická vrstva nad vlastním snímkem. Grafit a meruňka, původní geometrické značky, čitelnost nad každým podkladem. Všechen terén v tomto balíčku je smyšlený.</p><p><a href="README.md">Implementační poznámky</a> · <a href="validation.json">Ověření</a> · <a href="tokens.css">Tokeny</a></p><section><h2>01 / Hlavní modul · 1280 × 800</h2><a href="viewer.html"><img src="viewer.png" alt="Mapový modul se zvýrazněnými body a detailem"></a></section><section><h2>02 / Klik → nový bod</h2><a href="viewer.html?add"><img src="viewer-add.png" alt="Formulář nového bodu"></a></section><section><h2>03 / Raid · 1100 × 760</h2><a href="raid.html"><img src="raid.png" alt="Raid overlay"></a><p>Vyhledávání v maketě: Power Cable / sell / recycle → tři stavy doporučení.</p><div class="comparison"><img src="lookup-sell.png" alt="Prodat"><img src="lookup-recycle.png" alt="Recyklovat"></div></section><section><h2>04 / Prázdné stavy</h2><a href="empty.html"><img src="empty.png" alt="Bez snímku"></a><a href="raid-empty.html"><img src="raid-empty.png" alt="Bez aktivního plánu"></a></section><section><h2>05 / Původní ikony · 16 / 20 / 24 px</h2><div class="icon-matrix">'+matrix+'</div><p>Samostatné SVG a PNG sprite sheety; pořadí v manifestu. <a href="assets/sprites/icons-24.png">PNG sprite 24 px</a></p></section><section><h2>06 / 13 typů místa · barva + glyf + jméno</h2><div class="swatches">'+swatches+'</div><h3>Stejné značky nad třemi podklady</h3><img src="palette.png" alt="Paleta na tmavém, šedém a světlém podkladu"><h3>Světlé téma legendy</h3><div data-theme="light" class="tone light"><div class="swatches">'+swatches+'</div></div></section><section><h2>07 / Sladění snímku · pouze podklad</h2><div class="comparison"><div><h3>Před</h3><img src="terrain-before.png" alt="Původní smyšlený terén"></div><div><h3>Po</h3><img src="terrain-after.png" alt="Barevně sladěný smyšlený terén"></div></div><p><code>saturate(.38) sepia(.22) hue-rotate(345deg) brightness(.72) contrast(.92)</code></p></section><section><h2>08 / Stavy</h2><div class="state-samples">'+states+'</div><p>Glow se nehýbe. Výběr používá bílý obrys, shoda s plánem přerušovaný rámeček. Utlumené body si zachovávají neprůhledný podklad.</p></section><section><h2>Vlastní revize</h2><p>Silné stránky: oddělené významy typu bodu a místa, offline soubory, dvojitá kontura nad libovolným snímkem, viditelný kontext plánu. Rizika: husté shluky, nízká výška a náhrada snímku s jiným výřezem. Při implementaci zajistit seskupování, seznam bodů pro klávesnici a kontrolu registrace snímku. Tato maketa neověřuje nativní fokus overlaye ani čtení skutečné mapy.</p></section></div>'
put('review.html',page('Mapové návrhy',review,False))
palette='<div style="width:1000px">'+''.join('<div style="background:'+bg+';padding:22px;display:flex;gap:12px;flex-wrap:wrap">'+''.join(f'<span class="map-pin" style="position:static;transform:none;display:inline-flex;align-items:center;width:auto;gap:6px;color:{d};height:44px;padding:8px">{ic("area-"+n.lower().replace(" ","-"))}<span style="font:11px Inter">{n}</span></span>' for n,g,d,l,p in areas)+'</div>' for bg in ['#171D20','#777777','#F2EEE7'])+'</div>'
put('palette.html',page('Paleta',palette,False))
